{
  "name": "阿吉伦特涡轮分子真空泵",
  "name_en": "Agilent turbomolecular vacuum pump",
  "manufacturer": "Agilent",
  "description": "阿吉伦特涡轮分子真空泵是一种用于抽取真空腔体气体、建立和维持高真空环境的真空设备，常用于实验装置、分析仪器和高真空或超高真空系统。",
  "description_en": "An Agilent turbomolecular vacuum pump is a vacuum device used to remove gas from vacuum chambers and create or maintain high-vacuum conditions, commonly used in laboratory instruments, experimental systems, and high- or ultra-high-vacuum setups.",
  "tag_hints": [
    "turbomolecular pump",
    "high vacuum",
    "vacuum pumping",
    "UHV systems",
    "vacuum chamber",
    "Agilent vacuum"
  ],
  "actions": [
    {
      "action_name": "auto-on",
      "description": "开启涡轮分子真空泵。",
      "description_en": "Turn on the turbomolecular vacuum pump."
    },
    {
      "action_name": "auto-off",
      "description": "关闭涡轮分子真空泵。",
      "description_en": "Turn off the turbomolecular vacuum pump."
    },
    {
      "action_name": "auto-info",
      "description": "获取泵的运行信息。",
      "description_en": "Get the pump status and operating information."
    },
    {
      "action_name": "auto-pressure",
      "description": "获取压力读数。",
      "description_en": "Get the reported pressure reading."
    },
    {
      "action_name": "auto-egu",
      "description": "获取压力单位。",
      "description_en": "Get the pressure engineering units."
    }
  ]
}

